const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, '..', 'assets', 'words');
const files = fs
  .readdirSync(dir)
  .filter((f) => /^l(\d{2})-(\d{3})\.png$/.test(f))
  .sort();

const entries = files.map((f) => {
  const [, lesson, order] = f.match(/^l(\d{2})-(\d{3})\.png$/);
  const key = `${Number(lesson)}-${Number(order)}`;
  return `  '${key}': require('../../assets/words/${f}'),`;
});

const out = `import type { ImageSourcePropType } from 'react-native';
import type { VocabWord } from '../types';

/** Auto-generated by scripts/write-word-image-map.js — do not edit by hand. */
const images: Record<string, ImageSourcePropType> = {
${entries.join('\n')}
};

export function getWordImage(word: VocabWord | undefined): ImageSourcePropType | undefined {
  if (!word) {
    return undefined;
  }
  return images[\`\${word.lesson}-\${word.order}\`];
}
`;

fs.writeFileSync(path.join(__dirname, '..', 'src', 'data', 'wordImages.ts'), out);
console.log('wrote', files.length, 'image requires');
